ALTER TABLE public.voucher_batches DROP CONSTRAINT voucher_batches_requested_check;
ALTER TABLE public.voucher_batches ADD CONSTRAINT voucher_batches_requested_check CHECK (requested BETWEEN 1 AND 1500);
ALTER TABLE public.voucher_batches ADD COLUMN issue_config jsonb;
ALTER TABLE public.voucher_items ADD COLUMN attempts integer NOT NULL DEFAULT 0;
CREATE FUNCTION public.begin_voucher_batch(b jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtext(b->>'request_key')); SELECT id INTO bid FROM voucher_batches WHERE request_key=(b->>'request_key')::uuid AND owner_id=(b->>'owner_id')::uuid; IF bid IS NOT NULL THEN RETURN bid; END IF; IF NOT EXISTS(SELECT 1 FROM routers WHERE id=(b->>'router_id')::uuid AND owner_id=(b->>'owner_id')::uuid) THEN RAISE EXCEPTION 'not_allowed'; END IF; INSERT INTO voucher_batches(owner_id,router_id,source,package_name,package_snapshot,label,requested,mode,request_key,state,issue_config) VALUES((b->>'owner_id')::uuid,(b->>'router_id')::uuid,b->>'source',b->>'package_name',b->'package_snapshot',b->>'label',(b->>'requested')::integer,b->>'mode',(b->>'request_key')::uuid,'preparing',b->'issue_config') RETURNING id INTO bid; RETURN bid; END $$;
CREATE FUNCTION public.append_voucher_chunk(bid uuid,uid uuid,start_at integer,items jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b voucher_batches; n integer; r jsonb; BEGIN SELECT * INTO b FROM voucher_batches WHERE id=bid AND owner_id=uid FOR UPDATE; IF b.id IS NULL THEN RAISE EXCEPTION 'not_allowed'; END IF; SELECT count(*) INTO n FROM voucher_items WHERE batch_id=bid; IF b.state<>'preparing' OR start_at<n THEN RETURN n; END IF; IF start_at<>n OR jsonb_array_length(items) NOT BETWEEN 1 AND 100 OR n+jsonb_array_length(items)>b.requested THEN RAISE EXCEPTION 'invalid_chunk'; END IF; FOR r IN SELECT value FROM jsonb_array_elements(items) LOOP IF (r->>'ordinal')::integer<>n OR (r->>'name') !~ '^[A-Za-z0-9._@-]{1,32}$' OR COALESCE(r->>'ciphertext','')='' THEN RAISE EXCEPTION 'invalid_item'; END IF; IF EXISTS(SELECT 1 FROM router_cards WHERE router_id=b.router_id AND source=b.source AND name=r->>'name') THEN RAISE EXCEPTION 'number_exists' USING ERRCODE='23505'; END IF; INSERT INTO voucher_items(id,batch_id,owner_id,router_id,source,name,ordinal) VALUES((r->>'id')::uuid,bid,uid,b.router_id,b.source,r->>'name',n); INSERT INTO voucher_secrets(item_id,ciphertext) VALUES((r->>'id')::uuid,r->>'ciphertext'); n:=n+1; END LOOP; IF n=b.requested THEN UPDATE voucher_batches SET state='pending' WHERE id=bid; END IF; RETURN n; END $$;
CREATE FUNCTION public.voucher_batch_summary(bids uuid[]) RETURNS TABLE(batch_id uuid,prepared bigint,confirmed bigint,failed bigint,sent bigint,pending bigint,uncertain bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT batch_id,count(*),count(*) FILTER(WHERE state='confirmed'),count(*) FILTER(WHERE state='failed'),count(*) FILTER(WHERE state='sent'),count(*) FILTER(WHERE state='pending'),count(*) FILTER(WHERE state='uncertain') FROM voucher_items WHERE batch_id=ANY(bids) AND owner_id=auth.uid() GROUP BY batch_id $$;
CREATE OR REPLACE FUNCTION public.claim_voucher_item(rid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i voucher_items; b voucher_batches; BEGIN PERFORM pg_advisory_xact_lock(hashtext(rid::text)); IF EXISTS(SELECT 1 FROM voucher_items WHERE router_id=rid AND state='sent' AND lease_at>now()-interval '2 minutes') THEN RETURN NULL; END IF; UPDATE voucher_items SET state='uncertain',result='confirmation_timeout' WHERE router_id=rid AND state='sent' AND lease_at<now()-interval '2 minutes' AND attempts>=3; SELECT vi.* INTO i FROM voucher_items vi JOIN voucher_batches vb ON vb.id=vi.batch_id JOIN voucher_secrets vs ON vs.item_id=vi.id WHERE vi.router_id=rid AND vb.state='pending' AND vi.secret_valid AND vi.attempts<3 AND (vi.state='pending' OR (vi.state='sent' AND vi.lease_at<now()-interval '2 minutes')) ORDER BY vb.created_at,vi.ordinal FOR UPDATE OF vi SKIP LOCKED LIMIT 1; IF i.id IS NULL THEN RETURN NULL; END IF; UPDATE voucher_items SET state='sent',lease_at=now(),attempts=attempts+1 WHERE id=i.id; SELECT * INTO b FROM voucher_batches WHERE id=i.batch_id; RETURN jsonb_build_object('item',to_jsonb(i),'batch',to_jsonb(b)); END $$;
CREATE OR REPLACE FUNCTION public.retry_voucher_batch(bid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE voucher_items SET state='pending',lease_at=NULL,attempts=0 WHERE batch_id=bid AND state IN ('failed','uncertain') AND secret_valid; UPDATE voucher_batches SET state='pending' WHERE id=bid AND state IN ('complete','pending','paused'); END $$;
REVOKE ALL ON FUNCTION public.begin_voucher_batch(jsonb),public.append_voucher_chunk(uuid,uuid,integer,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.begin_voucher_batch(jsonb),public.append_voucher_chunk(uuid,uuid,integer,jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.voucher_batch_summary(uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.voucher_batch_summary(uuid[]) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.claim_voucher_item(uuid),public.retry_voucher_batch(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_voucher_item(uuid),public.retry_voucher_batch(uuid) TO service_role;